import type { SupabaseClient } from "@supabase/supabase-js";
import { encodeForWeb } from "./encode";

/**
 * Asset persistence: generated bytes go to the platform's own storage bucket
 * and are recorded in `media_assets`. The canonical document then references
 * the stable public URL — never a provider CDN link that expires.
 *
 * Images are resized and re-encoded first (`encodeForWeb`), and the width,
 * height and byte size of what was actually stored are recorded and returned:
 * the figure markup declares them. If the encoder cannot read the provider's
 * bytes, the original is stored as it came and the dimensions stay unknown
 * (null) rather than guessed.
 */

export const MEDIA_BUCKET = "article-media";

const EXTENSIONS: Record<string, string> = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/webp": "webp",
};

export interface StoreImageInput {
  supabase: SupabaseClient;
  userId: string;
  businessId?: string | null;
  articleId: string;
  kind: "hero" | "inline";
  /** Position among inline images; ignored for the hero. */
  index?: number;
  bytes: Uint8Array;
  mimeType: string;
  provider: string;
  model: string;
  prompt: string;
  costUsd: number;
}

export interface StoredImage {
  url: string;
  storagePath: string;
  /** Pixel size of the stored file; null when it could not be measured. */
  width: number | null;
  height: number | null;
  /** Size of the stored file. */
  bytes: number;
  mimeType: string;
}

interface Prepared {
  bytes: Uint8Array;
  mimeType: string;
  width: number | null;
  height: number | null;
}

async function prepare(input: StoreImageInput): Promise<Prepared> {
  try {
    return await encodeForWeb(input.bytes);
  } catch (err) {
    console.warn(
      JSON.stringify({
        level: "warn",
        event: "media_asset.encode_failed",
        article_id: input.articleId,
        kind: input.kind,
        error: err instanceof Error ? err.message : String(err),
      })
    );
    return { bytes: input.bytes, mimeType: input.mimeType, width: null, height: null };
  }
}

export async function storeImage(input: StoreImageInput): Promise<StoredImage> {
  const { supabase, userId, articleId, kind } = input;
  const prepared = await prepare(input);
  const extension = EXTENSIONS[prepared.mimeType] ?? "png";
  const name = kind === "hero" ? "hero" : `inline-${input.index ?? 0}`;
  // Content-addressed enough to be re-runnable: a regenerated asset for the
  // same slot overwrites its predecessor instead of accumulating.
  const storagePath = `${userId}/${articleId}/${name}.${extension}`;

  const { error: uploadError } = await supabase.storage
    .from(MEDIA_BUCKET)
    .upload(storagePath, prepared.bytes, { contentType: prepared.mimeType, upsert: true });

  if (uploadError) {
    throw new Error(`Failed to store ${kind} image: ${uploadError.message}`);
  }

  const { data } = supabase.storage.from(MEDIA_BUCKET).getPublicUrl(storagePath);
  const url = data.publicUrl;

  const ledger = {
    user_id: userId,
    business_id: input.businessId ?? null,
    article_id: articleId,
    kind,
    provider: input.provider,
    prompt: input.prompt.slice(0, 2000),
    url,
    storage_path: storagePath,
    meta: {
      model: input.model,
      mime_type: prepared.mimeType,
      cost_usd: input.costUsd,
      source_mime_type: input.mimeType,
      source_bytes: input.bytes.byteLength,
    },
  };
  const size = { width: prepared.width, height: prepared.height, bytes: prepared.bytes.byteLength };

  let { error: recordError } = await supabase.from("media_assets").insert({ ...ledger, ...size });
  if (recordError && /width|height|bytes|column/i.test(recordError.message)) {
    // The size columns are a later migration. The row carries the cost of the
    // render, so it is written without them rather than lost.
    ({ error: recordError } = await supabase
      .from("media_assets")
      .insert({ ...ledger, meta: { ...ledger.meta, ...size } }));
  }
  if (recordError) {
    // The asset exists and is referenced; a missing ledger row is a warning,
    // not a failure that should cost the article its image.
    console.warn(
      JSON.stringify({ level: "warn", event: "media_asset.record_failed", error: recordError.message })
    );
  }

  return {
    url,
    storagePath,
    width: prepared.width,
    height: prepared.height,
    bytes: prepared.bytes.byteLength,
    mimeType: prepared.mimeType,
  };
}

export async function recordVideoAsset(input: {
  supabase: SupabaseClient;
  userId: string;
  businessId?: string | null;
  articleId: string;
  provider: string;
  url: string;
  meta: Record<string, unknown>;
}): Promise<void> {
  const { error } = await input.supabase.from("media_assets").insert({
    user_id: input.userId,
    business_id: input.businessId ?? null,
    article_id: input.articleId,
    kind: "video",
    provider: input.provider,
    url: input.url,
    meta: input.meta,
  });
  if (error) {
    console.warn(
      JSON.stringify({ level: "warn", event: "media_asset.record_failed", error: error.message })
    );
  }
}
